	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)

	source, err := NewSnapshotStore(ctx,
		zaptest.NewLogger(t),
		store,
		ref,
		opts...)
	require.NoError(t, err)

	t.Cleanup(func() {
		_ = source.Close()
	})

	return source, target
}

